#if OPENNET_TESTING
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using NetworkHub.App;
using NetworkHub.Dns;
namespace NetworkHub.Desktop;
internal static class TestsHb
{
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
 static void Reject(Action action){bool rejected=false;try{action();}catch(Exception){rejected=true;}Check(rejected,"Unsafe operation succeeded");}
 static IDnsJournalStore Store(AppFiles files)=>new DnsFileJournalStore(Path.Combine(files.Data,"hb-unit-"+Guid.NewGuid().ToString("N")),"safe-test");
 sealed class Offline : IDnsSettingsReader {readonly TestsDns.FakeSettings fake;internal Offline(TestsDns.FakeSettings fake)=>this.fake=fake;public System.Collections.Generic.IReadOnlyList<DnsAdapter> Adapters()=>Array.Empty<DnsAdapter>();public DnsSnapshot Read(Guid id)=>fake.Read(id);}
 internal static void Headless(Action<string,Action> test,AppFiles files)
 {
  test("HB isolated Standard and offline recovery data paths stay inside the dedicated root",()=>{string local=Path.Combine(files.Root,"fake-user-local"),dir=Path.Combine(local,"Open Net HB Experiment");Check(AppFiles.DataAllowed(Path.Combine(files.Root,"exe"),dir,local)&&AppFiles.DataAllowed(Path.Combine(files.Root,"exe"),Path.Combine(dir,"RecoveryRequests/request"),local),"Dedicated root rejected");Check(!AppFiles.DataAllowed(Path.Combine(files.Root,"exe"),Path.Combine(local,"Open Net HB Experiment foreign"),local),"Neighbour root accepted");});
  test("HB automatic Comss GeoHide automatic touches only IPv4",()=>{var fake=TestsDns.Fixture();fake.State=fake.State.With(DnsFamily.IPv4,new(DnsMode.Automatic,Array.Empty<string>(),new[]{"192.0.2.1"}));var v6=fake.State.IPv6;var store=Store(files);foreach(DnsProfile? profile in new DnsProfile?[]{SimpleDns.Presets[0],SimpleDns.Presets[1],null}){var before=fake.State;SimpleDns.Change(fake,fake,store,"safe-test",before,SimpleDns.Plan(before,profile),profile==null);Check(fake.State.IPv6.SameConfiguration(v6),"IPv6 changed");}Check(fake.State.IPv4.Mode==DnsMode.Automatic&&fake.Writes==3,"Off did not reset assignment");});
  test("HB simulated application restart and reboot re-read persisted adapter state",()=>{string dir=Path.Combine(files.Data,"hb-reboot-"+Guid.NewGuid().ToString("N"));var first=TestsDns.Fixture(dir);var before=first.State;SimpleDns.Change(first,first,Store(files),"safe-test",before,SimpleDns.Plan(before,SimpleDns.Presets[0]),false);var fresh=TestsDns.Fixture(dir);Check(SimpleDns.Match(fresh.Read(before.AdapterId),SimpleDns.Presets)?.Id=="hb:comss","Fresh backend lost actual persisted state");fresh.State=fresh.State.With(DnsFamily.IPv4,new(DnsMode.Automatic,Array.Empty<string>(),Array.Empty<string>()));Check(SimpleDns.Match(fresh.State,SimpleDns.Presets)==null,"Network reset retained a UI enabled flag");});
  test("HB repeat saves emergency original and reads fact after restart",()=>{var fake=TestsDns.Fixture();var store=Store(files);var before=fake.State;var target=SimpleDns.Plan(before,SimpleDns.Presets[0]);SimpleDns.Change(fake,fake,store,"safe-test",before,target,false);before=fake.State;SimpleDns.Change(fake,fake,store,"safe-test",before,before,false);Check(fake.Writes==2&&store.Load(before.AdapterId)!.Before.SameConfiguration(before),"Repeat failed or backup was not pre-write state");Check(SimpleDns.Match(fake.State,SimpleDns.Presets)?.Id=="hb:comss","Restart needs a UI switch to infer state");});
  test("HB manual DNS off means automatic and emergency can restore manual encryption",()=>{var fake=TestsDns.Fixture();var original=fake.State with{IPv4=fake.State.IPv4 with{Encryption=fake.State.IPv4.Servers.Select(s=>new DnsDohSettings(s,"https://dns.example.test/dns-query",2)).ToArray()}};fake.State=original;var store=Store(files);SimpleDns.Change(fake,fake,store,"safe-test",original,SimpleDns.Plan(original,null),true);Check(fake.State.IPv4.Mode==DnsMode.Automatic,"Off silently restored manual");new DnsTransaction(fake,fake,store,"safe-test").Restore(original.AdapterId,fake.State.Fingerprint());Check(fake.State.SameConfiguration(original),"Emergency lost original DoH");});
  test("HB preserves DoH on provider switch and requires consent for plaintext custom",()=>{var fake=TestsDns.Fixture();var encrypted=fake.State with{IPv4=fake.State.IPv4 with{Encryption=fake.State.IPv4.Servers.Select(s=>new DnsDohSettings(s,"https://dns.example.test/dns-query",2)).ToArray()}};var plan=SimpleDns.Plan(encrypted,SimpleDns.Presets[0]);Check(plan.IPv4.Encryption.All(p=>p.Template==SimpleDns.Presets[0].Doh&&p.Flags==2),"Encryption weakened");var custom=new DnsProfile("custom","Custom",new[]{"8.8.8.8"},Array.Empty<string>(),null,"","",true,"");Reject(()=>SimpleDns.Plan(encrypted,custom));Check(SimpleDns.Plan(encrypted,custom,true).IPv4.ComparableEncryption().Length==0,"Explicit plain plan failed");});
  test("HB disconnected virtual and changed-network snapshots fail without writes",()=>{var fake=TestsDns.Fixture();var before=fake.State;fake.State=before with{DependencyFingerprint="new network"};Reject(()=>SimpleDns.Change(fake,fake,Store(files),"safe-test",before,SimpleDns.Plan(before,SimpleDns.Presets[0]),false));Check(fake.Writes==0,"Stale network written");Reject(()=>SimpleDns.Change(new Offline(fake),fake,Store(files),"safe-test",fake.State,SimpleDns.Plan(fake.State,SimpleDns.Presets[0]),false));Check(fake.Writes==0,"Disconnected adapter written");foreach(string kind in new[]{"Tunnel","Ppp","Loopback"})Check(!SimpleDns.Eligible(new(Guid.NewGuid(),"VPN",kind,true,true)),"Virtual accepted");Check(!SimpleDns.Eligible(new(Guid.NewGuid(),"WiFi","Wireless80211",false,false)),"Disconnected accepted");});
  test("HB write error rolls back and retains verified evidence",()=>{var fake=TestsDns.Fixture();var before=fake.State;bool once=false;fake.BeforeWrite=_=>{if(!once){once=true;throw new IOException("write denied");}};var evidence=new DnsOperationEvidence();Reject(()=>SimpleDns.Change(fake,fake,Store(files),"safe-test",before,SimpleDns.Plan(before,SimpleDns.Presets[0]),false,evidence));Check(fake.State.SameConfiguration(before)&&evidence.RecoveryResult=="verified","Failure falsely succeeded");});
  test("HB partial write and failed rollback preserve an offline record",()=>{var fake=TestsDns.Fixture();var before=fake.State;var target=SimpleDns.Plan(before,SimpleDns.Presets[0]);var store=Store(files);fake.BeforeWrite=_=>{fake.State=target;throw new IOException("partial failure");};Reject(()=>SimpleDns.Change(fake,fake,store,"safe-test",before,target,false));Check(store.Load(before.AdapterId)?.Active==true&&store.Load(before.AdapterId)!.Before.SameConfiguration(before),"Partial failure lost backup");fake.BeforeWrite=null;new DnsTransaction(fake,fake,store,"safe-test").Restore(before.AdapterId,fake.State.Fingerprint());Check(fake.State.SameConfiguration(before),"Restarted emergency restore failed");});
  test("HB verification mismatch cannot become success",()=>{var fake=TestsDns.Fixture();var before=fake.State;bool once=false;fake.AfterWrite=()=>{if(!once){once=true;fake.ReadOverride=s=>{fake.ReadOverride=null;return s with{DependencyFingerprint="readback mismatch"};};}};Reject(()=>SimpleDns.Change(fake,fake,Store(files),"safe-test",before,SimpleDns.Plan(before,SimpleDns.Presets[0]),false));});
  test("HB custom DNS validates canonical IPv4 and preserves builtin catalogue",()=>{string id=Guid.NewGuid().ToString("N");foreach(string first in new[]{"","not-an-ip","8","0.0.0.0","127.0.0.1","224.0.0.1","8.8.8.8:53","2001:db8::1"})Reject(()=>SimpleDns.Custom(id,"Custom",first,""));Reject(()=>SimpleDns.Custom(id,"","8.8.8.8",""));Reject(()=>SimpleDns.Custom(id,"Custom","8.8.8.8","8.8.8.8"));var value=SimpleDns.Custom(id,"Custom","8.8.8.8","8.8.4.4");var store=new DnsProfileStore(Path.Combine(files.Data,"hb-custom"),"HbDnsProfiles.json");store.Save(value);store.Save(value with{Name="Edited"});Check(store.Load().Single().Name=="Edited"&&SimpleDns.Presets.Length==5,"Edit modified presets");store.Delete(id);Check(store.Load().Length==0,"Delete failed");});
  test("HB external adapter configuration controls state without a persisted enabled flag",()=>{var fake=TestsDns.Fixture();var on=SimpleDns.Plan(fake.State,SimpleDns.Presets[0]);Check(SimpleDns.Match(on,SimpleDns.Presets)?.Name=="Comss.one","Actual preset not detected");Check(SimpleDns.Match(fake.State,SimpleDns.Presets)==null,"Foreign manual DNS claimed preset");var automatic=on.With(DnsFamily.IPv4,new(DnsMode.Automatic,Array.Empty<string>(),SimpleDns.Presets[0].IPv4));Check(SimpleDns.Match(automatic,SimpleDns.Presets)==null,"DHCP effective addresses treated as manual profile");});
 }
 static SimpleDnsView View(Shell shell)=>(SimpleDnsView)typeof(Shell).GetField("dnsWindow",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.GetValue(shell)!;
 internal static async Task Ui(Shell shell,AppFiles files,Func<string,Func<Task>,Task> test)
 {
  await test("HB actual UI enable profile change disable cache custom editor and restart simulation",async()=>{var isolated=new AppFiles(Path.Combine(files.Root,"test-results/hb-ui-"+Guid.NewGuid().ToString("N")));using var instance=new SingleInstance(isolated.Data,isolated.Log);var fake=TestsDns.Fixture(isolated.Data);HbDnsController.ReaderForTests=fake;var preview=new Shell(isolated,true,instance);try{preview.Window.Show();preview.OpenDnsSettings();var view=View(preview);int confirmations=0;view.ConfirmationForTests=_=>{confirmations++;return true;};Check(await view.Power(false)&&view.Applied,"On did not apply");L.Set("ru");view.Window.UpdateLayout();TestsR2.Capture((FrameworkElement)view.Window.Content,Path.Combine(files.Data,"hb-enabled-comss.png"));int first=confirmations;Check(await view.Power(false)&&confirmations==first,"Repeat asked session confirmation");HbDnsController.FaultForTests=_=>new System.ComponentModel.Win32Exception(1223);view.SelectProfile("hb:magic");for(int i=0;i<200&&view.IsBusy;i++)await Task.Delay(20);HbDnsController.FaultForTests=null;Check(view.Selected?.Id=="hb:comss"&&view.CurrentProfile=="Comss.one","Declined provider switch changed displayed selection");view.SelectProfile("hb:geo");for(int i=0;i<200&&view.IsBusy;i++)await Task.Delay(20);Check(view.CurrentProfile=="GeoHide EU","Active profile selection did not apply");view.Window.UpdateLayout();TestsR2.Capture((FrameworkElement)view.Window.Content,Path.Combine(files.Data,"hb-enabled-geohide.png"));Check(await view.Power(true)&&fake.State.IPv4.Mode==DnsMode.Automatic,"Off did not reset");view.Window.UpdateLayout();TestsR2.Capture((FrameworkElement)view.Window.Content,Path.Combine(files.Data,"hb-disabled-auto.png"));int writes=fake.Writes;await view.ClearCache();Check(fake.Writes==writes,"Cache changed DNS");view.EditCustom();var editor=preview.Window.OwnedWindows.Cast<Window>().SelectMany(w=>w.OwnedWindows.Cast<Window>()).FirstOrDefault(w=>w.FindName("HbCustomSave")!=null)??preview.Window.OwnedWindows.Cast<Window>().Single(w=>w.FindName("HbCustomSave")!=null);((TextBox)editor.FindName("HbCustomName")).Text="Custom test";((TextBox)editor.FindName("HbCustomFirst")).Text="8.8.8.8";((TextBox)editor.FindName("HbCustomSecond")).Text="8.8.4.4";editor.UpdateLayout();Check(LocalizedTree.Walk(editor).OfType<ScrollViewer>().First().ScrollableHeight==0,"New custom form needlessly scrolls");TestsR2.Capture((FrameworkElement)editor.Content,Path.Combine(files.Data,"hb-custom-editor.png"));((Button)editor.FindName("HbCustomSave")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(view.Selected?.Name=="Custom test","Custom save not selected");Check(await view.Power(false)&&fake.State.IPv4.Servers[0]=="8.8.8.8","Custom did not apply");view.Window.Close();preview.OpenDnsSettings();view=View(preview);view.ConfirmationForTests=_=>true;Check(view.Applied&&view.CurrentProfile=="Custom test","Restart lost factual state");foreach(string language in new[]{"ru","en"})foreach(string theme in new[]{"dark","light"}){L.Set(language);ThemeManager.SetMode(theme);view.Window.UpdateLayout();TestsR2.Capture((FrameworkElement)view.Window.Content,Path.Combine(files.Data,$"hb-dns-{language}-{theme}.png"));preview.Window.UpdateLayout();TestsR2.Capture((FrameworkElement)preview.Window.Content,Path.Combine(files.Data,$"hb-main-{language}-{theme}.png"));}Check(await view.Power(true),"Restored host could not turn off");view.Window.Close();}finally{preview.Dispose();preview.Window.Close();HbDnsController.ReaderForTests=null;HbDnsController.FaultForTests=null;shell.ApplySettings(shell.Settings.Copy());}});
  await test("HB UAC and cache failure do not claim enabled or clear settings",async()=>{shell.OpenDnsSettings();var view=View(shell);var before=view.Controller.Current;view.ConfirmationForTests=_=>true;try{HbDnsController.FaultForTests=_=>new System.ComponentModel.Win32Exception(1223,"Simulated UAC denial");Check(!await view.Power(false),"UAC failure succeeded");Check(shell.Find<TextBlock>("Message").Text.Length>0,"Main switch error hidden in unopened settings");Check(view.Controller.Current!.SameConfiguration(before!),"UAC failure changed mock DNS");await view.ClearCache();Check(view.Controller.Current!.SameConfiguration(before!),"Cache failure changed DNS");}finally{HbDnsController.FaultForTests=null;view.ConfirmationForTests=null;view.Window.Close();}});
 }
}
#endif
